head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDSTF05908.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_LIST_NM + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd);
};
scwin.fn_search2 = function() {
    var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_LIST_MGR + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD2.BindColVal;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts2.DataID = encodeURI(url);
    dts2.reset();
    $c.cm.ShowWin(grd2);
};
scwin.fn_search3 = function() {
    var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_LIST_PRC + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD3.BindColVal;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts3.DataID = encodeURI(url);
    dts3.reset();
    $c.cm.ShowWin(grd3);
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = rdo_ISUR_CD.getValue(); // 발행사/기초자산 구분값

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = rdo_ISUR_CD.getValue(); // 발행사/기초자산 구분값

};
scwin.fn_GetParUpdate2 = function(arrPar, param_dts) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = cmb_ISUR_CD2.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD2.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts2.getCellData(dts2.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = "1"; // 발행사/기초자산 구분값

    $c.stf.CopyDataSet(dts_ElwInst2, param_dts);
};
scwin.fn_GetParNew2 = function(arrPar, param_dts) {
    // 신규생성시 지정하는 평션
    arrPar[0] = cmb_ISUR_CD2.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD2.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = "1"; // 발행사/기초자산 구분값

    $c.stf.CopyDataSet(dts_ElwInst2, param_dts);
};
scwin.fn_GetParUpdate3 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = cmb_ISUR_CD3.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD3.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts3.getCellData(dts3.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = rdo_ISUR_CD3.getValue(); // 발행사/기초자산 구분값

};
scwin.fn_GetParNew3 = function(arrPar, param_dts) {
    // 신규생성시 지정하는 평션
    arrPar[0] = cmb_ISUR_CD3.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD3.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = rdo_ISUR_CD3.getValue(); // 발행사/기초자산 구분값

};
scwin.fn_newpre_create_frame = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../lstproc/ULDSTF05909.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 상호변경", 50, 50, 1180, 630, "window");
    if (chk_VALID_OBJ_1 != true) {
        /* 상호명 변경(발행사) */
        dts_ElwInst_E1.DataID = "/CodeAction.do?method=validComChgListWrntCd&For=C";
        dts_ElwInst_E1.Reset();

        /* 상호명 변경(기초자산) */
        dts_ElwUly_E1.DataID = "/CodeAction.do?method=validComChgListElwUlyCd&For=C";
        dts_ElwUly_E1.Reset();
    }
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_newpre_create_frame2 = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../lstproc/ULDSTF05910.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 흡수합병", 10, 10, 1265, 625, "window");
    if (chk_VALID_OBJ_2 != true) {
        /* 흡수합병 */
        dts_ElwInst_E2.DataID = "/CodeAction.do?method=validMergeListWrntCd&For=C";
        dts_ElwInst_E2.Reset();
    }
    scwin.fn_search2(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_newpre_create_frame3 = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../lstproc/ULDSTF05911.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 행사가격/전환비율 변경", 200, 100, 1000, 490, "window");
    if (chk_VALID_OBJ_3 != true) {
        /* 행사가격 */
        dts_ElwInst_E3.DataID = "/CodeAction.do?method=validExerPrcListWrntCd&For=C";
        dts_ElwInst_E3.Reset();

        /* 상호명 변경(기초자산) */
        dts_ElwUly_E3.DataID = "/CodeAction.do?method=validExerPrcListElwUlyCd&For=C";
        dts_ElwUly_E3.Reset();
    }
    scwin.fn_search3(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
scwin.fn_ValidWrntObj = function() {
    /* 상호명 변경(발행사) */
    dts_ElwInst_E1.DataID = "/CodeAction.do?method=validComChgListWrntCd&For=C";
    dts_ElwInst_E1.Reset();

    /* 흡수합병 */
    dts_ElwInst_E2.DataID = "/CodeAction.do?method=validMergeListWrntCd&For=C";
    dts_ElwInst_E2.Reset();

    /* 행사가격 */
    dts_ElwInst_E3.DataID = "/CodeAction.do?method=validExerPrcListWrntCd&For=C";
    dts_ElwInst_E3.Reset();

    /* 상호명 변경(기초자산) */
    dts_ElwUly_E1.DataID = "/CodeAction.do?method=validComChgListElwUlyCd&For=C";
    dts_ElwUly_E1.Reset();

    /* 상호명 변경(기초자산) */
    dts_ElwUly_E3.DataID = "/CodeAction.do?method=validExerPrcListElwUlyCd&For=C";
    dts_ElwUly_E3.Reset();
};
scwin.fn_get_isurcode = function() {
    //elw발행사
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=C";
    dts_ElwInst.Reset();
    dts_ElwUly.DataID = "/CodeAction.do?method=listElwUlyCd&For=C";
    dts_ElwUly.Reset();
    $c.stf.CopyDataSet(dts_ElwInst, dts_ElwInst2);
    cmb_ISUR_CD2.setSelectedIndex(0);
    $c.stf.CopyDataSet(dts_ElwInst, dts_ElwInst3);
    cmb_ISUR_CD3.setSelectedIndex(0);
    $c.stf.CopyDataSet(dts_ElwUly, dts_ElwUly3);
};
scwin.img_Search_onclick = function() {
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD.focus();
        return;
    }
    scwin.fn_search();
};
scwin.img_Search2_onclick = function() {
    if (cmb_ISUR_CD2.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD2.focus();
        return;
    }
    scwin.fn_search2();
};
scwin.img_Search3_onclick = function() {
    if (cmb_ISUR_CD3.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD3.focus();
        return;
    }
    scwin.fn_search3();
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총 " + rowcount + " 건");
    dts.setRowPosition(rowcount, 0);
    $c.cm.CloseWin(rowcount, grd);
};
scwin.dts2_OnLoadError = function() {
    $c.stf.alert_error(dts2);
};
scwin.dts2_OnLoadCompleted = function(rowcount) {
    txb_TotCnt2.setValue("총 " + rowcount + " 건");
    dts2.setRowPosition(rowcount, 0);
    $c.cm.CloseWin(rowcount, grd2);
};
scwin.dts3_OnLoadError = function() {
    $c.stf.alert_error(dts3);
};
scwin.dts3_OnLoadCompleted = function(rowcount) {
    txb_TotCnt3.setValue("총 " + rowcount + " 건");
    dts3.setRowPosition(rowcount, 0);
    $c.cm.CloseWin(rowcount, grd3);
};
scwin.img_Close_onclick = function() {
    window.close();
};
scwin.img_Close2_onclick = function() {
    window.close();
};
scwin.img_Close3_onclick = function() {
    window.close();
};
scwin.img_Regist_onclick = function() {
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame();
};
scwin.img_Regist2_onclick = function() {
    if (cmb_ISUR_CD2.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD2.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew2;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame2();
};
scwin.img_Regist3_onclick = function() {
    if (cmb_ISUR_CD3.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD3.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew3;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame3();
};
scwin.img_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "상호명 변경내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Excel2_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts2.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd2, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "흡수합병내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Excel3_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts3.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd3, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "행사가격/전환비율 변경내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame();
};
scwin.grd2_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate2; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame2();
};
scwin.grd3_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate3; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame3();
};
scwin.rdo_ISUR_CD_OnSelChange = function() {
    if (rdo_ISUR_CD.getValue() == "1") {
        if (chk_VALID_OBJ_1.checked == true) {
            cmb_ISUR_CD.ComboDataID = "dts_ElwInst_E1";
        } else {
            cmb_ISUR_CD.ComboDataID = "dts_ElwInst";
        }
    } else if (rdo_ISUR_CD.getValue() == "2") {
        if (chk_VALID_OBJ_1.checked == true) {
            cmb_ISUR_CD.ComboDataID = "dts_ElwUly_E1";
        } else {
            cmb_ISUR_CD.ComboDataID = "dts_ElwUly";
        }
    }
    cmb_ISUR_CD.setSelectedIndex(0);
};
scwin.rdo_ISUR_CD3_OnSelChange = function() {
    if (rdo_ISUR_CD3.getValue() == "1") {
        if (chk_VALID_OBJ_3.checked == true) {
            cmb_ISUR_CD3.ComboDataID = "dts_ElwInst_E3";
        } else {
            cmb_ISUR_CD3.ComboDataID = "dts_ElwInst3";
        }
    } else if (rdo_ISUR_CD3.getValue() == "2") {
        if (chk_VALID_OBJ_3.checked == true) {
            cmb_ISUR_CD3.ComboDataID = "dts_ElwUly_E3";
        } else {
            cmb_ISUR_CD3.ComboDataID = "dts_ElwUly3";
        }
    }
    cmb_ISUR_CD3.setSelectedIndex(0);
};
scwin.cmb_ISUR_CD_OnSelChange2 = function() {
    if (cmb_ISUR_CD.getSelectedIndex() != 0) scwin.fn_search();
};
scwin.cmb_ISUR_CD_OnSelected = function() {

};
scwin.cmb_ISUR_CD2_OnSelChange2 = function() {
    if (cmb_ISUR_CD2.getSelectedIndex() != 0) {
        scwin.fn_search2();
    }
};
scwin.cmb_ISUR_CD2_OnSelected = function() {

};
scwin.cmb_ISUR_CD3_OnSelChange2 = function() {
    if (cmb_ISUR_CD3.getSelectedIndex() != 0) {
        scwin.fn_search3();
    }
};
scwin.cmb_ISUR_CD3_OnSelected = function() {

};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd3);
    rdo_ISUR_CD.setValue("1");
    rdo_ISUR_CD3.setValue("1");
    scwin.fn_get_isurcode();
    scwin.fn_ValidWrntObj();
    img_Elwlist.setSelectedTabIndex(1);
};
scwin.chk_VALID_OBJ_1_onclick = function() {
    if (chk_VALID_OBJ_1.checked == true) {
        if (rdo_ISUR_CD.getValue() == "1") {
            // 발행사	
            cmb_ISUR_CD.ComboDataID = "dts_ElwInst_E1";
        } else if (rdo_ISUR_CD.getValue() == "2") {
            cmb_ISUR_CD.ComboDataID = "dts_ElwUly_E1";
        }
    } else {
        if (rdo_ISUR_CD.getValue() == "1") {
            // 발행사	
            cmb_ISUR_CD.ComboDataID = "dts_ElwInst";
        } else if (rdo_ISUR_CD.getValue() == "2") {
            cmb_ISUR_CD.ComboDataID = "dts_ElwUly";
        }
    }
    cmb_ISUR_CD.setSelectedIndex(0);
};
scwin.chk_VALID_OBJ_2_onclick = function() {
    if (chk_VALID_OBJ_2.checked == true) {
        cmb_ISUR_CD2.ComboDataID = "dts_ElwInst_E2";
    } else {
        cmb_ISUR_CD2.ComboDataID = "dts_ElwInst2";
    }
    cmb_ISUR_CD2.setSelectedIndex(0);
};
scwin.chk_VALID_OBJ_3_onclick = function() {
    if (chk_VALID_OBJ_3.checked == true) {
        if (rdo_ISUR_CD3.getValue() == "1") {
            // 발행사	
            cmb_ISUR_CD3.ComboDataID = "dts_ElwInst_E3";
        } else if (rdo_ISUR_CD3.getValue() == "2") {
            cmb_ISUR_CD3.ComboDataID = "dts_ElwUly_E3";
        }
    } else {
        if (rdo_ISUR_CD3.getValue() == "1") {
            // 발행사	
            cmb_ISUR_CD3.ComboDataID = "dts_ElwInst";
        } else if (rdo_ISUR_CD3.getValue() == "2") {
            cmb_ISUR_CD3.ComboDataID = "dts_ElwUly3";
        }
    }
    cmb_ISUR_CD3.setSelectedIndex(0);
};
